alter table public.antimicrobial_therapies add column if not exists source text not null default 'patient_record'; alter table public.antimicrobial_therapies add column if not exists laboratory_result_id uuid null references public.microbiology_results(id) on delete set null; alter table public.antimicrobial_therapies add column if not exists laboratory_sample_id uuid null references public.laboratory_samples(id) on delete set null; alter table public.antimicrobial_therapies drop constraint if exists antimicrobial_therapies_source_check; alter table public.antimicrobial_therapies add constraint antimicrobial_therapies_source_check check (source in ('patient_record','laboratory')); create index if not exists antimicrobial_therapies_laboratory_result_idx on public.antimicrobial_therapies(laboratory_result_id) where laboratory_result_id is not null; create index if not exists antimicrobial_therapies_laboratory_sample_idx on public.antimicrobial_therapies(laboratory_sample_id) where laboratory_sample_id is not null;
